import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.BbQUUm7J.js";const u=JSON.parse('{"title":"x402 Micropayments (furlpay x402)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/x402.md","filePath":"guide/x402.md","lastUpdated":1794934948000}'),s={name:"guide/x402.md"};function o(l,e,r,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="x402-micropayments-furlpay-x402" tabindex="-1">x402 Micropayments (<code>furlpay x402</code>) <a class="header-anchor" href="#x402-micropayments-furlpay-x402" aria-label="Permalink to &quot;x402 Micropayments (`furlpay x402`)&quot;">​</a></h1><p>Autonomous machine-to-machine micropayments over the HTTP 402 <code>Payment Required</code> protocol, with EIP-712 cryptographic authorization and a TigerBeetle-style double-entry netting model.</p><div class="warning custom-block"><p class="custom-block-title">Honesty label</p><p>There is <strong>no live TigerBeetle connection in this build</strong> — settlement runs as a clearly-labeled local simulation. Every response says <code>SIMULATED</code> / <code>LOCAL_SIMULATION</code>, and simulated tx ids carry the <code>furlpay_simnet_</code> prefix. The MCP tool <code>furlpay_settle_invoice</code> is labeled identically.</p></div><h2 id="settle-a-challenge" tabindex="-1">Settle a challenge <a class="header-anchor" href="#settle-a-challenge" aria-label="Permalink to &quot;Settle a challenge&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x402</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pay</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --challenge-header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;WWW-Authenticate: x402 recipient=&quot;GBLX99API&quot;, amount=&quot;0.0005&quot;, token=&quot;USDC&quot;&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max-cost</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.005</span></span></code></pre></div><h2 id="replay-protection" tabindex="-1">Replay protection <a class="header-anchor" href="#replay-protection" aria-label="Permalink to &quot;Replay protection&quot;">​</a></h2><p>Consumed payment nonces are tracked in a <strong>file-locked atomic ledger</strong> under <code>~/.furlpay/</code> — not an in-memory <code>Set</code>. A signed EIP-712 payment authorization replayed in a later CLI invocation is rejected: nonce state survives process restarts.</p><h2 id="agent-gatekeeping" tabindex="-1">Agent gatekeeping <a class="header-anchor" href="#agent-gatekeeping" aria-label="Permalink to &quot;Agent gatekeeping&quot;">​</a></h2><p>When an MCP agent settles a challenge, the <strong>agent policy gate fires before settlement</strong>: read-validate-record under the policy lock, so concurrent tool calls cannot both pass against a stale spend snapshot. With no policy on disk the settlement stays in simulation mode — it never moves value. Note the MCP default: <code>furlpay_settle_invoice</code> is a value-moving tool, so it is structurally absent from tools/list until <code>--enable-execution</code> + a configured policy, and even then it runs through the two-phase preview→confirm protocol (readiness P7).</p><h2 id="the-netting-model" tabindex="-1">The netting model <a class="header-anchor" href="#the-netting-model" aria-label="Permalink to &quot;The netting model&quot;">​</a></h2><p>The engine models debits, credits and pending transfers with deterministic, microsecond-order semantics — the same double-entry discipline the facilitator would enforce against a live TigerBeetle cluster. What is simulated here is the <em>ledger transport</em>, not the accounting: netting arithmetic is real integer math.</p><h2 id="live-enablement-path" tabindex="-1">Live enablement path <a class="header-anchor" href="#live-enablement-path" aria-label="Permalink to &quot;Live enablement path&quot;">​</a></h2><p>Wiring a live facilitator means replacing the simulated settlement sink with an authenticated facilitator endpoint; the challenge parser, nonce ledger and netting math stay as-is. Until then, every response is labeled simulated — the CLI never prints a settlement it did not perform.</p>',13)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
